3. **Event Tracking**
   ```typescript
   // Track custom events
   export function trackHotjarEvent(eventName: string, data?: any) {
     if (typeof window !== 'undefined' && window.hj) {
       window.hj('event', eventName);

       // Track additional data
       if (data) {
         window.hj('identify', data.userId, data);
       }
     }
   }

   // Usage examples:
   trackHotjarEvent('subscription_started');
   trackHotjarEvent('ai_query_completed');
   trackHotjarEvent('dashboard_viewed');
   ```

## Layer 4: Operations & Marketing Automation

### Zapier Integration

#### Setup Webhooks

1. **Create Zapier Account** and set up Zaps for:
   - New user registration → Add to mailing list
   - Subscription created → Update CRM
   - High usage alert → Notify sales team
   - Churn risk → Trigger retention campaign

2. **Webhook Endpoints**
   ```typescript
   // src/app/api/webhooks/zapier/route.ts
   export async function POST(request: Request) {
     const data = await request.json();

     // Verify webhook authenticity
     const signature = request.headers.get('x-zapier-signature');
     if (!verifyZapierSignature(data, signature)) {
       return new Response('Unauthorized', { status: 401 });
     }

     // Process webhook based on type
     switch (data.event_type) {
       case 'user.created':
         await handleNewUser(data.user);
         break;
       case 'subscription.created':
         await handleNewSubscription(data.subscription);
         break;
       case 'usage.threshold':
         await handleUsageAlert(data.usage);
         break;
     }

     return new Response('OK', { status: 200 });
   }
   ```

