use_subscription_content = '''\'use client\'

import { useEffect, useState, useCallback } from 'react'
import { useAuth } from './useAuth'
import { supabase } from '@/lib/supabase'

interface SubscriptionData {
  id: string
  status: 'active' | 'canceled' | 'past_due' | 'trialing' | 'incomplete'
  plan_name: string
  plan_price: number
  currency: string
  interval: 'month' | 'year'
  current_period_start: string
  current_period_end: string
  cancel_at_period_end: boolean
  stripe_subscription_id: string
  stripe_customer_id: string
}

interface UsageData {
  api_calls_used: number
  api_calls_limit: number
  usage_percentage: number
  reset_date: string
  daily_usage: Array<{
    date: string
    calls: number
  }>
}

export function useSubscription() {
  const { user } = useAuth()
  const [subscription, setSubscription] = useState<SubscriptionData | null>(null)
  const [usage, setUsage] = useState<UsageData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchSubscription = useCallback(async () => {
    if (!user) return

    try {
      setLoading(true)
      setError(null)

      // Fetch subscription data
      const { data: subData, error: subError } = await supabase
        .from('subscriptions')
        .select('*')
        .eq('user_id', user.id)
        .single()

      if (subError && subError.code !== 'PGRST116') {
        throw subError
      }

      setSubscription(subData)

      // Fetch usage data from profile
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('api_calls_used, api_calls_limit')
        .eq('id', user.id)
        .single()

      if (profileError) {
        throw profileError
      }

      // Calculate usage percentage
      const usagePercentage = profileData.api_calls_limit > 0 
        ? (profileData.api_calls_used / profileData.api_calls_limit) * 100
        : 0

      // Get current period end for reset date
      const resetDate = subData?.current_period_end || 
        new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // Default to 30 days

      // Fetch daily usage (last 30 days)
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString()
      const { data: usageData } = await supabase
        .from('usage_logs')
        .select('created_at, tokens_used')
        .eq('user_id', user.id)
        .gte('created_at', thirtyDaysAgo)
        .order('created_at', { ascending: true })

      // Aggregate daily usage
      const dailyUsage = aggregateDailyUsage(usageData || [])

      setUsage({
        api_calls_used: profileData.api_calls_used,
        api_calls_limit: profileData.api_calls_limit,
        usage_percentage: usagePercentage,
        reset_date: resetDate,
        daily_usage: dailyUsage
      })

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch subscription')
      console.error('Error fetching subscription:', err)
    } finally {
      setLoading(false)
    }
  }, [user])

  useEffect(() => {
    fetchSubscription()
  }, [fetchSubscription])

  // Real-time subscription to usage updates
  useEffect(() => {
    if (!user) return

    const channel = supabase
      .channel('subscription_updates')
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'subscriptions',
        filter: `user_id=eq.${user.id}`
      }, () => {
        fetchSubscription()
      })
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public', 
        table: 'profiles',
        filter: `id=eq.${user.id}`
      }, () => {
        fetchSubscription()
      })
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [user, fetchSubscription])

  const createCheckoutSession = async (priceId: string) => {
    try {
      const response = await fetch('/api/subscription/create-checkout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          price_id: priceId,
          success_url: `${window.location.origin}/dashboard?success=true`,
          cancel_url: `${window.location.origin}/pricing`,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Failed to create checkout session')
      }

      // Redirect to Stripe Checkout
      if (data.url) {
        window.location.href = data.url
      }

      return data
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create checkout')
      throw err
    }
  }

  const cancelSubscription = async () => {
    try {
      const response = await fetch('/api/subscription/cancel', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          subscription_id: subscription?.stripe_subscription_id,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Failed to cancel subscription')
      }

      await fetchSubscription()
      return data
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to cancel subscription')
      throw err
    }
  }

  const updateSubscription = async (newPriceId: string) => {
    try {
      const response = await fetch('/api/subscription/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          subscription_id: subscription?.stripe_subscription_id,
          new_price_id: newPriceId,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Failed to update subscription')
      }

      await fetchSubscription()
      return data
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update subscription')
      throw err
    }
  }

  const isFeatureAvailable = (feature: string): boolean => {
    if (!subscription) return false

    const featureAccess = {
      basic: ['chat', 'basic_analysis'],
      pro: ['chat', 'basic_analysis', 'advanced_analysis', 'batch_processing'],
      enterprise: ['chat', 'basic_analysis', 'advanced_analysis', 'batch_processing', 'priority_support', 'custom_models']
    }

    const planFeatures = featureAccess[subscription.plan_name as keyof typeof featureAccess] || []
    return planFeatures.includes(feature)
  }

  return {
    subscription,
    usage,
    loading,
    error,
    createCheckoutSession,
    cancelSubscription,
    updateSubscription,
    refreshSubscription: fetchSubscription,
    isFeatureAvailable,
  }
}

// Helper function to aggregate daily usage
function aggregateDailyUsage(usageData: Array<{ created_at: string; tokens_used: number }>) {
  const dailyMap = new Map<string, number>()

  usageData.forEach(item => {
    const date = item.created_at.split('T')[0] // Get date part only
    const current = dailyMap.get(date) || 0
    dailyMap.set(date, current + (item.tokens_used || 1))
  })

  return Array.from(dailyMap.entries())
    .map(([date, calls]) => ({ date, calls }))
    .sort((a, b) => a.date.localeCompare(b.date))
}

// Hook for checking subscription limits
export function useSubscriptionLimits() {
  const { usage, subscription } = useSubscription()

  const canMakeRequest = usage ? usage.api_calls_used < usage.api_calls_limit : false
  const remainingCalls = usage ? Math.max(0, usage.api_calls_limit - usage.api_calls_used) : 0
  const isNearLimit = usage ? usage.usage_percentage > 80 : false
  const hasActiveSubscription = subscription?.status === 'active'

  return {
    canMakeRequest,
    remainingCalls,
    isNearLimit,
    hasActiveSubscription,
    usagePercentage: usage?.usage_percentage || 0,
  }
}
